\begin{definition}
\label{def:5-30-extra-1}



For a map $\Phi:M\to N$ and $c\in N$, the fiber $\Phi^{-1}(c)$ is the
\emph{level set} of $\Phi$ at $c$. If $N=\mathbb R^k$ and $c=0$, it is the
\emph{zero set} of $\Phi$.
\end{definition}

